local a=peripheral.find("inventory")if not a or not peripheral.hasType(a,"inventory")then return nil end;local b=a;b.itemTypes={}b.index={}b.index.defaultMaxCount=64;b.index.isIndexed=false;b.index.latestLog={}function b.index.index()b.index.isIndexed=false;table.insert(b.index.latestLog,"starting indexing ...")local c=b.list()for d,e in pairs(c)do if e and not b.itemTypes[e.name]then local f,details=pcall(b.getItemDetail,d)if f and details then b.itemTypes[e.name]={name=e.name,displayName=details.displayName,maxCount=details.maxCount}end;sleep(0)end;table.insert(b.index.latestLog,"indexing: "..math.floor(d/#c*100).."%")end;b.index.isIndexed=true;table.insert(b.index.latestLog,"indexing completed.")end;function b.count()local g=0;for d,e in pairs(b.list())do if e~=nil and e.count~=nil then g=g+e.count end end;return g end;function b.maxCount()local g=(b.size()-#b.list())*b.index.defaultMaxCount;for d,e in pairs(b.list())do if e~=nil then if b.itemTypes[e.name]then g=g+b.itemTypes[e.name].maxCount else success,details=pcall(b.getItemDetail,d)if success then g=g+details.maxCount else g=g+b.index.defaultMaxCount end;sleep(0)end else g=g+b.index.defaultMaxCount end end;return g end;function b.percentage()return math.floor(b.count()/b.maxCount()*100)end;return b
